#!/usr/bin/env python3
"""
Parallel TF-IDF Indexing and Search.

Implements parallel index building and batch search while preserving
identical results to the sequential reference implementation.
"""

from __future__ import annotations

import math
import os
import time
import multiprocessing as mp
from collections import defaultdict
from concurrent.futures import ProcessPoolExecutor
from dataclasses import dataclass
from heapq import nlargest

from document_generator import Document
from sequential import TFIDFIndex, SearchResult, compute_term_frequencies, tokenize


@dataclass
class ParallelIndexingResult:
    """Result from parallel index building."""

    index: TFIDFIndex
    elapsed_time: float
    num_documents: int
    vocabulary_size: int


def _get_mp_context() -> mp.context.BaseContext:
    try:
        return mp.get_context("fork")
    except ValueError:
        return mp.get_context()


def _chunk_documents(documents: list[Document], chunk_size: int) -> list[list[Document]]:
    if chunk_size <= 0:
        chunk_size = 1
    return [documents[i : i + chunk_size] for i in range(0, len(documents), chunk_size)]


def _process_docs_chunk(chunk: list[Document]) -> tuple[list[tuple[int, dict[str, float]]], dict[str, int]]:
    doc_tfs: list[tuple[int, dict[str, float]]] = []
    df_counts: dict[str, int] = defaultdict(int)

    for doc in chunk:
        text = f"{doc.title} {doc.content}"
        tokens = tokenize(text)
        tf = compute_term_frequencies(tokens)
        doc_tfs.append((doc.doc_id, tf))
        for term in tf.keys():
            df_counts[term] += 1

    return doc_tfs, dict(df_counts)


def build_tfidf_index_parallel(
    documents: list[Document],
    num_workers: int | None = None,
    chunk_size: int = 500,
) -> ParallelIndexingResult:
    """
    Build TF-IDF inverted index in parallel.

    Returns a ParallelIndexingResult with the same TFIDFIndex structure
    as the sequential implementation.
    """
    start_time = time.perf_counter()

    index = TFIDFIndex()
    index.num_documents = len(documents)

    if not documents:
        elapsed = time.perf_counter() - start_time
        return ParallelIndexingResult(index=index, elapsed_time=elapsed, num_documents=0, vocabulary_size=0)

    if num_workers is None:
        num_workers = os.cpu_count() or 1
    num_workers = max(1, num_workers)

    chunks = _chunk_documents(documents, chunk_size)
    if num_workers > len(chunks):
        num_workers = len(chunks)

    if num_workers <= 1 or len(chunks) == 1:
        chunk_results = [_process_docs_chunk(chunk) for chunk in chunks]
    else:
        ctx = _get_mp_context()
        with ProcessPoolExecutor(max_workers=num_workers, mp_context=ctx) as executor:
            chunk_results = list(executor.map(_process_docs_chunk, chunks))

    doc_term_freqs: dict[int, dict[str, float]] = {}
    doc_id_order: list[int] = []
    df_counts_total: dict[str, int] = defaultdict(int)

    for doc_tfs, df_counts in chunk_results:
        for doc_id, tf in doc_tfs:
            doc_term_freqs[doc_id] = tf
            doc_id_order.append(doc_id)
        for term, count in df_counts.items():
            df_counts_total[term] += count

    index.vocabulary = set(df_counts_total.keys())
    index.document_frequencies = dict(df_counts_total)

    # IDF(t) = log(N / DF(t)) + 1
    N = index.num_documents
    for term, df in index.document_frequencies.items():
        index.idf[term] = math.log(N / df) + 1

    inverted_index: dict[str, list[tuple[int, float]]] = defaultdict(list)
    for doc_id in doc_id_order:
        tf_dict = doc_term_freqs[doc_id]
        for term, tf in tf_dict.items():
            tfidf = tf * index.idf[term]
            inverted_index[term].append((doc_id, tfidf))

    index.inverted_index = {}
    for term, posting_list in inverted_index.items():
        posting_list.sort(key=lambda x: x[1], reverse=True)
        index.inverted_index[term] = posting_list

    for doc_id in doc_id_order:
        tf_dict = doc_term_freqs[doc_id]
        doc_vector: dict[str, float] = {}
        norm_squared = 0.0
        for term, tf in tf_dict.items():
            tfidf = tf * index.idf[term]
            doc_vector[term] = tfidf
            norm_squared += tfidf * tfidf
        index.doc_vectors[doc_id] = doc_vector
        index.doc_norms[doc_id] = math.sqrt(norm_squared)

    elapsed = time.perf_counter() - start_time
    return ParallelIndexingResult(
        index=index,
        elapsed_time=elapsed,
        num_documents=len(documents),
        vocabulary_size=len(index.vocabulary),
    )


def _search_query_local(
    query: str,
    index: TFIDFIndex,
    top_k: int,
    doc_titles: dict[int, str],
) -> list[SearchResult]:
    query_tokens = tokenize(query)
    if not query_tokens:
        return []

    query_tf = compute_term_frequencies(query_tokens)

    query_vector: dict[str, float] = {}
    query_norm_squared = 0.0
    for term, tf in query_tf.items():
        if term in index.idf:
            tfidf = tf * index.idf[term]
            query_vector[term] = tfidf
            query_norm_squared += tfidf * tfidf

    if not query_vector:
        return []

    query_norm = math.sqrt(query_norm_squared)

    candidate_docs: set[int] = set()
    for term in query_vector:
        if term in index.inverted_index:
            for doc_id, _ in index.inverted_index[term]:
                candidate_docs.add(doc_id)

    scores: list[tuple[int, float]] = []
    for doc_id in candidate_docs:
        doc_vector = index.doc_vectors.get(doc_id, {})
        doc_norm = index.doc_norms.get(doc_id, 0)

        if doc_norm == 0:
            continue

        dot_product = sum(query_vector.get(term, 0) * doc_vector.get(term, 0) for term in query_vector)
        similarity = dot_product / (query_norm * doc_norm)
        scores.append((doc_id, similarity))

    top_results = nlargest(top_k, scores, key=lambda x: x[1])

    results: list[SearchResult] = []
    for doc_id, score in top_results:
        title = doc_titles.get(doc_id, f"Document {doc_id}")
        results.append(SearchResult(doc_id=doc_id, score=score, title=title))

    return results


_SEARCH_INDEX: TFIDFIndex | None = None
_SEARCH_DOC_TITLES: dict[int, str] | None = None
_SEARCH_TOP_K: int = 10


def _init_search_worker(index: TFIDFIndex, doc_titles: dict[int, str], top_k: int) -> None:
    global _SEARCH_INDEX, _SEARCH_DOC_TITLES, _SEARCH_TOP_K
    _SEARCH_INDEX = index
    _SEARCH_DOC_TITLES = doc_titles
    _SEARCH_TOP_K = top_k


def _search_query_worker(query: str) -> list[SearchResult]:
    return _search_query_local(query, _SEARCH_INDEX, _SEARCH_TOP_K, _SEARCH_DOC_TITLES or {})


def batch_search_parallel(
    queries: list[str],
    index: TFIDFIndex,
    top_k: int = 10,
    num_workers: int | None = None,
    documents: list[Document] | None = None,
) -> tuple[list[list[SearchResult]], float]:
    """
    Search multiple queries in parallel.

    Returns (results, elapsed_time).
    """
    start_time = time.perf_counter()

    if not queries:
        return [], time.perf_counter() - start_time

    if num_workers is None:
        num_workers = os.cpu_count() or 1
    num_workers = max(1, num_workers)
    if num_workers > len(queries):
        num_workers = len(queries)

    doc_titles = {d.doc_id: d.title for d in documents} if documents else {}

    if num_workers <= 1 or len(queries) == 1:
        results = [_search_query_local(query, index, top_k, doc_titles) for query in queries]
        return results, time.perf_counter() - start_time

    ctx = _get_mp_context()
    if ctx.get_start_method() == "fork":
        _init_search_worker(index, doc_titles, top_k)
        with ProcessPoolExecutor(max_workers=num_workers, mp_context=ctx) as executor:
            results = list(executor.map(_search_query_worker, queries))
    else:
        with ProcessPoolExecutor(
            max_workers=num_workers,
            mp_context=ctx,
            initializer=_init_search_worker,
            initargs=(index, doc_titles, top_k),
        ) as executor:
            results = list(executor.map(_search_query_worker, queries))

    elapsed = time.perf_counter() - start_time
    return results, elapsed
